#!/usr/bin/env node
// Audio is added after rendering; no audio assets are generated by this command.
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { registerHooks } from 'node:module';
import { readFile, writeFile, mkdir, mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { dirname, extname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { parseArgs } from 'node:util';
const exec = promisify(execFile);
const helper = fileURLToPath(new URL('./sound-analysis.py', import.meta.url));

/** Legacy spans are in TIMELINE seconds, never composition seconds. */
export function parseTypingSpans(value) {
  if (value === undefined) return [];
  return value.split(',').map((span) => {
    const match = /^(\d+(?:\.\d+)?)-(\d+(?:\.\d+)?)$/.exec(span);
    const startMs = Number(match?.[1]) * 1000;
    const endMs = Number(match?.[2]) * 1000;
    if (!match || !Number.isFinite(endMs) || !(endMs > startMs)) throw new Error(`Invalid typing span: ${span}`);
    return { startMs, endMs };
  });
}

/** Global offset search, constrained to a single continuous slice of the track. */
export function chooseMusicOffset(beats, majorSeconds, durationSeconds, musicDurationSeconds, ending = {}) {
  const maxOffset = musicDurationSeconds - durationSeconds;
  if (maxOffset < 0) throw new Error('Music is shorter than the video; supply a longer continuous track');
  if (!beats.length) throw new Error('No music beats detected');
  let minimum = 0, maximum = maxOffset;
  if (Number.isFinite(ending.finalHitSeconds) && Number.isFinite(ending.endCardSeconds)) {
    minimum = Math.max(0, ending.finalHitSeconds - durationSeconds + 0.001);
    maximum = Math.min(maxOffset, ending.finalHitSeconds - ending.endCardSeconds);
    if (minimum > maximum) throw new Error('Final music hit cannot fit the end card with this continuous track');
  }
  const distance = (time) => {
    let lo = 0, hi = beats.length;
    while (lo < hi) { const mid = (lo + hi) >>> 1; if (beats[mid] < time) lo = mid + 1; else hi = mid; }
    return Math.min(Math.abs((beats[lo] ?? Infinity) - time), Math.abs((beats[lo - 1] ?? -Infinity) - time));
  };
  const cues = majorSeconds.length ? majorSeconds : [0];
  let best = { offsetSeconds: 0, meanBeatErrorMs: Infinity };
  for (let offset = Math.ceil(minimum * 200) / 200; offset <= maximum + 1e-9; offset += 0.005) {
    const error = cues.reduce((sum, cue) => sum + distance(cue + offset), 0) / cues.length * 1000;
    if (error < best.meanBeatErrorMs - 1e-7) best = { offsetSeconds: Number(offset.toFixed(3)), meanBeatErrorMs: error };
  }
  if (!Number.isFinite(best.meanBeatErrorMs)) throw new Error('No offset can satisfy the end-card timing');
  return best;
}

export function parseEbur128(log) {
  const summary = log.slice(log.lastIndexOf('Summary:'));
  const integratedLufs = Number(/I:\s*(-?[\d.]+) LUFS/.exec(summary)?.[1]);
  const truePeakDbfs = Number(/Peak:\s*(-?[\d.]+) dBFS/.exec(summary)?.[1]);
  if (!Number.isFinite(integratedLufs) || !Number.isFinite(truePeakDbfs)) throw new Error('Cannot parse exported MP4 loudness');
  return { integratedLufs, truePeakDbfs };
}

// Correct from decoded AAC measurements, then re-encode from the original mix.
export function exportGainCorrection(levels) {
  const gain = Math.min(-16 - levels.integratedLufs, -4.4 - levels.truePeakDbfs);
  return levels.integratedLufs + gain >= -17 && levels.integratedLufs + gain <= -15 ? gain : null;
}

async function ffmpeg(args) {
  return exec('ffmpeg', ['-hide_banner', '-nostdin', ...args], { maxBuffer: 32 * 1024 * 1024 });
}

async function main() {
  const { values: args } = parseArgs({ options: Object.fromEntries(
    ['video', 'timeline', 'music', 'music-credit', 'sfx-dir', 'typing', 'music-offset', 'out'].map((key) => [key, { type: 'string' }]),
  ) });
  for (const key of ['video', 'timeline', 'music', 'music-credit', 'sfx-dir', 'out']) {
    if (!args[key]?.trim()) throw new Error(`Required: --${key}`);
  }
  const video = resolve(args.video), out = resolve(args.out), music = resolve(args.music), sfx = resolve(args['sfx-dir']);
  if (out === video) throw new Error('--out must be a copy, different from --video');
  const outputDir = dirname(out);
  await mkdir(outputDir, { recursive: true });
  const artifacts = outputDir;
  await mkdir(artifacts, { recursive: true });
  registerHooks({ resolve(specifier, context, next) {
    try { return next(specifier, context); }
    catch (error) {
      if (error.code !== 'ERR_MODULE_NOT_FOUND' || !specifier.startsWith('.') || extname(specifier)) throw error;
      return next(`${specifier}.ts`, context);
    }
  } });
  const { parseTimeline } = await import('../lib/timeline.ts');
  const { buildSoundCues } = await import('../lib/sound-cues.ts');
  const timeline = parseTimeline(await readFile(resolve(args.timeline), 'utf8'));
  const cueSheet = buildSoundCues(timeline, parseTypingSpans(args.typing));
  const { stdout: probe } = await exec('ffprobe', ['-v', 'error', '-select_streams', 'v:0', '-show_entries', 'stream=duration,avg_frame_rate:format=duration', '-of', 'json', video]);
  const metadata = JSON.parse(probe);
  const durationSeconds = Number(metadata.streams[0].duration ?? metadata.format.duration);
  const [num, den] = metadata.streams[0].avg_frame_rate.split('/').map(Number);
  if (!Number.isFinite(durationSeconds) || durationSeconds <= 0) throw new Error('Invalid video duration');
  if (Math.abs(durationSeconds * 1000 - cueSheet.durationMs) > Math.max(100, 2000 / (num / den))) {
    throw new Error(`Video/timeline duration mismatch: ${durationSeconds * 1000} vs ${cueSheet.durationMs} ms`);
  }
  const python = process.env.AUDIO_PYTHON || '/home/bbx/.venvs/audio/bin/python';
  const py = async (...command) => exec(python, [helper, ...command], {
    maxBuffer: 32 * 1024 * 1024, env: { ...process.env, MPLCONFIGDIR: join(tmpdir(), 'record-demo-matplotlib'), NUMBA_CACHE_DIR: join(tmpdir(), 'record-demo-numba') },
  });
  console.log('Detecting beats and checking low-band kick alignment…');
  await py('beats', music, artifacts);
  const beats = JSON.parse(await readFile(join(artifacts, 'beats.json'), 'utf8'));
  const majors = cueSheet.cues.filter((cue) => cue.major).map((cue) => cue.timeMs / 1000);
  const offsetArg = args['music-offset'] ?? 'auto';
  const sync = chooseMusicOffset(beats.beatsSeconds, majors, durationSeconds, beats.durationSeconds, offsetArg === 'auto' ? { finalHitSeconds: beats.finalHitSeconds, endCardSeconds: cueSheet.endCardMs === null ? undefined : cueSheet.endCardMs / 1000 } : {});
  if (offsetArg !== 'auto') {
    const offset = Number(offsetArg);
    if (!Number.isFinite(offset) || offset < 0 || offset + durationSeconds > beats.durationSeconds) throw new Error('Music offset must fit the continuous track');
    sync.offsetSeconds = offset;
    sync.meanBeatErrorMs = majors.length ? majors.reduce((sum, t) => sum + Math.min(...beats.beatsSeconds.map((b) => Math.abs(b - (t + offset)))), 0) / majors.length * 1000 : null;
  }
  const sheet = { ...cueSheet, videoDurationSeconds: durationSeconds, music: { file: music, credit: args['music-credit'], ...sync, finalHitSourceSeconds: beats.finalHitSeconds, finalHitCompositionSeconds: beats.finalHitSeconds - sync.offsetSeconds }, typingOverride: args.typing ?? null,
    majorBeatErrorsMs: majors.map((t) => ({ timeSeconds: t, errorMs: Math.min(...beats.beatsSeconds.map((b) => Math.abs(b - t - sync.offsetSeconds))) * 1000 })) };
  await writeFile(join(artifacts, 'cues.json'), JSON.stringify(sheet, null, 2) + '\n');
  const sfxCredits = await readFile(join(sfx, 'credits.txt'));
  await writeFile(join(artifacts, 'credits.txt'), Buffer.concat([Buffer.from(`${args['music-credit']}\n\n`), sfxCredits]));
  const temp = await mkdtemp(join(tmpdir(), 'record-demo-sound-'));
  try {
    console.log('Mixing supplied audio files…');
    await py('mix', music, sfx, join(artifacts, 'cues.json'), join(temp, 'mix.wav'), artifacts);
    // Tame sparse effect transients before normalization so the bed can reach -16 LUFS.
    const dynamics = 'acompressor=threshold=0.06:ratio=12:attack=0.1:release=80:makeup=1';
    const first = await ffmpeg(['-i', join(temp, 'mix.wav'), '-af', `${dynamics},loudnorm=I=-16:TP=-6.5:LRA=11:print_format=json`, '-f', 'null', '-']);
    const stats = JSON.parse(first.stderr.match(/\{\s*"input_i"[\s\S]*?\}/)?.[0] ?? '{}');
    for (const key of ['input_i', 'input_tp', 'input_lra', 'input_thresh', 'target_offset']) if (!Number.isFinite(Number(stats[key]))) throw new Error(`Invalid loudnorm measurement ${key}`);
    const norm = `${dynamics},loudnorm=I=-16:TP=-6.5:LRA=11:measured_I=${stats.input_i}:measured_TP=${stats.input_tp}:measured_LRA=${stats.input_lra}:measured_thresh=${stats.input_thresh}:offset=${stats.target_offset}:linear=true:print_format=json,aresample=48000`;
    // Limiter last, at the delivery rate: loudnorm runs at 192 kHz, and any gain applied after the
    // limiter (or a later resample) lets transient SFX overshoot the true-peak ceiling.
    const limiter = 'apad=pad_dur=0.005,alimiter=limit=0.5:level=false:attack=5:release=50,atrim=start=0.005,asetpts=PTS-STARTPTS';
    let levels, gainDb = 0;
    const attempts = [];
    for (let attempt = 0; attempt < 3; attempt++) {
      const encoded = await ffmpeg(['-y', '-i', video, '-i', join(temp, 'mix.wav'), '-map', '0:v:0', '-map', '1:a:0', '-c:v', 'copy', '-af', `${norm},volume=${gainDb}dB,${limiter}`, '-c:a', 'aac', '-b:a', '192k', '-ar', '48000', '-t', String(durationSeconds), '-movflags', '+faststart', out]);
      const measured = await ffmpeg(['-i', out, '-vn', '-af', 'ebur128=peak=true', '-f', 'null', '-']);
      await writeFile(join(artifacts, 'ebur128.txt'), measured.stderr);
      levels = parseEbur128(measured.stderr);
      attempts.push({ gainDb, levels, encodeLog: encoded.stderr });
      if (levels.integratedLufs >= -17 && levels.integratedLufs <= -15 && levels.truePeakDbfs < -4) break;
      const correction = exportGainCorrection(levels);
      if (correction === null) break;
      gainDb += correction;
    }
    await writeFile(join(artifacts, 'normalization.json'), JSON.stringify({ dynamics, limiter, firstPass: stats, attempts }, null, 2));
    await writeFile(join(artifacts, 'levels.json'), JSON.stringify(levels, null, 2) + '\n');
    if (levels.integratedLufs < -17 || levels.integratedLufs > -15 || levels.truePeakDbfs >= -4) throw new Error(`Export failed loudness limits: ${JSON.stringify(levels)}; see ${artifacts}`);
    console.log('Building cue proof from the exported MP4…');
    await py('proof', out, join(artifacts, 'cues.json'), artifacts);
    const checks = ['whoosh', 'click', 'typing', 'pop'].map((kind) => {
      const cue = sheet.cues.find((c) => c.kind === kind);
      return cue ? `${(cue.timeMs / 1000).toFixed(3)}s — ${kind}: ${cue.reason}` : `${kind}: no cue available`;
    });
    checks.push(`${((sheet.endCardMs ?? Math.max(0, durationSeconds * 1000 - 1000)) / 1000).toFixed(3)}s — end card / music fade`);
    await writeFile(join(artifacts, 'headphones.txt'), `Check these five moments by ear; measurements do not establish sound quality.\n${checks.join('\n')}\n`);
    console.log(JSON.stringify({ out, artifacts, ...levels, ...sync, cueCounts: sheet.cues.reduce((counts, c) => ({ ...counts, [c.kind]: (counts[c.kind] ?? 0) + 1 }), {}) }, null, 2));
  } finally { await rm(temp, { recursive: true, force: true }); }
}
if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  main().catch((error) => { console.error(error.stack ?? error); process.exitCode = 1; });
}
